bool DrivePickerBridgeStubDispatch::Accept(
    DrivePickerBridge* impl,
    mojo::Message* message) {
  switch (static_cast<messages::DrivePickerBridge>(message->header()->name)) {
    case messages::DrivePickerBridge::kShowDrivePicker: {
      DCHECK(message->is_serialized());
      internal::DrivePickerBridge_ShowDrivePicker_Params_Data* params =
          reinterpret_cast<internal::DrivePickerBridge_ShowDrivePicker_Params_Data*>(
              message->mutable_payload());
      

      // Validation for DrivePickerBridge.0
      bool success = true;
      ::mojo::PendingRemote<::drive_picker_host::mojom::DrivePickerResultHandler> p_result_handler{};
      DrivePickerKeysPtr p_keys{};
      DrivePickerBridge_ShowDrivePicker_ParamsDataView input_data_view(params, message);
      
      if (success) {
        p_result_handler =
            input_data_view.TakeResultHandler<decltype(p_result_handler)>();
      }
      if (success && !input_data_view.ReadKeys(&p_keys))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            DrivePickerBridge::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->ShowDrivePicker(        
        std::move(p_result_handler), 
        std::move(p_keys));
      return true;
    }
    case messages::DrivePickerBridge::kLoadConsentKitUrl: {
      DCHECK(message->is_serialized());
      internal::DrivePickerBridge_LoadConsentKitUrl_Params_Data* params =
          reinterpret_cast<internal::DrivePickerBridge_LoadConsentKitUrl_Params_Data*>(
              message->mutable_payload());
      

      // Validation for DrivePickerBridge.1
      bool success = true;
      ::GURL p_consent_kit_url{};
      DrivePickerBridge_LoadConsentKitUrl_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadConsentKitUrl(&p_consent_kit_url))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            DrivePickerBridge::Name_, 1, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->LoadConsentKitUrl(        
        std::move(p_consent_kit_url));
      return true;
    }
  }
  return false;
}

